diff --git a/expat/lib/xmlparse.c b/expat/lib/xmlparse.c
index c107214..a8a4dbd 100644
--- a/expat/lib/xmlparse.c
+++ b/expat/lib/xmlparse.c
@@ -6261,7 +6261,9 @@ doProlog(XML_Parser parser, const ENCODING *enc, const char *s, const char *end,
           return XML_ERROR_NO_MEMORY;
         name = el->name;
         dtd->scaffold[myindex].name = name;
-        nameLen = xcslen(name) + /*null terminator*/ 1;
+        /* Count only the characters here; the per-name NUL terminators
+           are reserved separately in build_model(). */
+        nameLen = xcslen(name);

         /* Detect and prevent integer overflow */
         if (nameLen > UINT_MAX - dtd->contentStringLen) {
@@ -8531,13 +8533,18 @@ build_model(XML_Parser parser) {
     return NULL;
   }
 #endif
+  /* The string area stores each name's characters followed by a single NUL
+     terminator.  contentStringLen counts only the characters, so reserve one
+     extra XML_Char per scaffold node -- a safe upper bound on the number of
+     name nodes -- to hold the terminators. */
+  const size_t stringCount = dtd->contentStringLen + dtd->scaffCount;
   if (dtd->scaffCount * sizeof(XML_Content)
-      > SIZE_MAX - dtd->contentStringLen * sizeof(XML_Char)) {
+      > SIZE_MAX - stringCount * sizeof(XML_Char)) {
     return NULL;
   }

   const size_t allocsize = (dtd->scaffCount * sizeof(XML_Content)
-                            + (dtd->contentStringLen * sizeof(XML_Char)));
+                            + (stringCount * sizeof(XML_Char)));

   // NOTE: We are avoiding MALLOC(..) here to so that
   //       applications that are not using XML_FreeContentModel but plain

